<?php

declare(strict_types=1);

namespace ForumRewrite\Llm;

/** Provenance is generated by input assemblers, never extracted from forum prose. */
final class ExchangeDependencies
{
    public static function manifest(array $ids, bool $complete = true): array
    {
        foreach ($ids as $id) {
            if (!self::validId($id)) return ['version' => 1, 'complete' => false, 'post_ids' => []];
        }
        $ids = array_values(array_unique($ids));
        sort($ids);
        return ['version' => 1, 'complete' => $complete, 'post_ids' => $ids];
    }

    public static function classify(array $exchange): ?array
    {
        $primary = $exchange['related_post_id'] ?? null;
        $context = $exchange['context'] ?? [];
        if (!is_array($context)) return null;
        if (array_key_exists('exchange_dependencies', $context)) {
            $manifest = $context['exchange_dependencies'];
            if (!is_array($manifest) || ($manifest['version'] ?? null) !== 1
                || ($manifest['complete'] ?? null) !== true
                || !is_array($manifest['post_ids'] ?? null) || !array_is_list($manifest['post_ids'])) return null;
            $ids = $manifest['post_ids'];
            foreach ($ids as $id) if (!self::validId($id)) return null;
            if ($primary !== null && (!self::validId($primary) || !in_array($primary, $ids, true))) return null;
            return array_values(array_unique($ids));
        }
        return self::legacyRootScore($exchange);
    }

    private static function legacyRootScore(array $exchange): ?array
    {
        if (($exchange['call_type'] ?? null) !== 'fast_post_score') return null;
        $payload = $exchange['request']['payload'] ?? null;
        if (!is_array($payload)) return null;
        $messages = $payload['messages'] ?? [];
        if (!is_array($messages) || !array_is_list($messages)) return null;
        $system = $payload['system'] ?? null;
        if (count($messages) === 2 && ($messages[0]['role'] ?? null) === 'system') {
            if ($system !== null) return null;
            $system = $messages[0]['content'] ?? null;
            $messages = [$messages[1]];
        }
        $expected = @file_get_contents(dirname(__DIR__, 3) . '/prompts/fast_post_scoring_system.txt');
        if (!is_string($expected) || trim($expected) === '') return null;
        $expected = trim($expected);
        if (!is_string($system) || trim($system) !== $expected || count($messages) !== 1
            || ($messages[0]['role'] ?? null) !== 'user' || !is_string($messages[0]['content'] ?? null)) return null;
        $input = json_decode($messages[0]['content'], true);
        if (!is_array($input) || array_diff(array_keys($input), ['post_id', 'content_hash', 'post_kind', 'post_text']) !== []
            || ($input['post_kind'] ?? null) !== 'thread' || !is_string($input['post_text'] ?? null)
            || !is_string($input['content_hash'] ?? null) || !self::validId($input['post_id'] ?? null)
            || $input['post_id'] !== ($exchange['related_post_id'] ?? null)) return null;
        return [$input['post_id']];
    }

    public static function validId(mixed $id): bool
    {
        return is_string($id) && preg_match('/^[A-Za-z0-9][A-Za-z0-9._-]*$/D', $id) === 1;
    }
}
